// 电商促销 · 风格样片。标准分镜：标题 → 花字 → 图片容器与高亮 → 数据 → 人名条 → 收尾。
// 可照搬：STYLE 取值、rays()（旋转放射底）、extrude()（立体厚度字）、impact()（冲击放大）、banner()（斜切标题底板）、
// capsule()（黑底黄字胶囊）、burst()（爆炸贴）、ribbon()（标签缎带）、ticket()（优惠券造型）、sparkle() / sparkles()（闪光），
// 以及 layers() 的分层写法：会动的元素各成一层，在本地坐标里画，位置/缩放/旋转/不透明度写进 pose(t)，运行时据此做运动模糊。

const STYLE = {
  color: {
    bgInner: "#FF3B30",
    bgOuter: "#B8000D",
    ray: "rgba(255,214,90,0.12)",
    yellow: "#FFE45C",
    gold: "#FFB000",
    deep: "#7A0008", // 立体厚度的暗面
    white: "#FFFFFF",
    ink: "#1A0A0A",
  },
  font: {
    title: '"Alimama ShuHeiTi", "HarmonyOS Sans SC", "Microsoft YaHei", sans-serif',
    number: '"Anton", "Bebas Neue", "Oswald", "Impact", sans-serif',
    body: '"HarmonyOS Sans SC", "Microsoft YaHei", sans-serif',
  },
};

// 快切：每段冲击入场，收走只要 0.15 s；下一段几乎同时砸进来。
const SCENES = { title: [0, 2.0], keyword: [1.92, 3.7], media: [3.62, 6.3], data: [6.27, 8.2], name: [8.12, 9.6], end: [9.52, 99] };
const COPY = {
  title: "把想法变成画面",
  keyword: { lead: "风格", key: "不走样" },
  media: "示意画面",
  data: { value: 87, unit: "%", label: "一次通过率" },
  name: { name: "痕继痕迹", role: "动效设计师" },
  end: "一个风格，处处一致",
};
// 全片同一个倾斜方向（约 -2.3°），同一画面不出现第二种角度。
const TILT = -0.04;

const clamp = (v) => Math.max(0, Math.min(1, v));
const backOut = (v, c = 1.2) => { v = clamp(v) - 1; return 1 + (c + 1) * v * v * v + c * v * v; };
const quintOut = (v) => 1 - Math.pow(1 - clamp(v), 5);
const cubicIn = (v) => clamp(v) ** 3;
const font = (weight, size, family) => `${weight} ${Math.round(size)}px ${family}`;
// 只写字体实际有的字重：阿里妈妈数黑体只有 Bold（700），Anton 只有常规（400）。写成 900 会被浏览器假加粗，
// 笔画变粗、字内空隙被填死（"画""想"这类复杂字最明显）。正文的 HarmonyOS Sans SC 有 Black，可以用 900。
const weightOf = (family) => (family === STYLE.font.title ? 700 : family === STYLE.font.number ? 400 : 900);

// 冲击放大：从 1.5 倍压到 1 倍，带约 6% 的回弹，0.3 s。返回缩放值；未开始返回 0。
function impact(t, start, dur = 0.3) {
  if (t < start) return 0;
  const k = clamp((t - start) / dur);
  return 1.5 - 0.5 * backOut(k);
}

function rays(ctx, t, w, h) {
  const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w * 0.65);
  g.addColorStop(0, STYLE.color.bgInner);
  g.addColorStop(1, STYLE.color.bgOuter);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
  ctx.save();
  ctx.translate(w / 2, h / 2);
  ctx.rotate(t * 0.15);
  ctx.fillStyle = STYLE.color.ray;
  const n = 18;
  for (let i = 0; i < n; i++) {
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.arc(0, 0, w, (i * 2 * Math.PI) / n, ((i + 0.5) * 2 * Math.PI) / n);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();
}

// 立体厚度：同一段字向右下叠若干层暗色，再盖亮面和描边。
function extrude(ctx, text, x, y, size, face, side, u, family = STYLE.font.title, align = "center") {
  ctx.font = font(weightOf(family), size, family);
  ctx.textAlign = align;
  ctx.lineJoin = "round";
  const depth = Math.max(4, Math.round(size * 0.07));
  for (let i = depth; i > 0; i--) {
    ctx.fillStyle = side;
    ctx.fillText(text, x + i * 0.8, y + i);
  }
  ctx.lineWidth = Math.min(size * 0.08, 8 * u);
  ctx.strokeStyle = STYLE.color.deep;
  ctx.strokeText(text, x, y);
  ctx.fillStyle = face;
  ctx.fillText(text, x, y);
  ctx.textAlign = "left";
}

// 标题底板：斜切的深红长条，金色描边 + 硬投影，像大促横幅。本地坐标以中心为原点。
function banner(ctx, bw, bh, u) {
  const skew = bh * 0.35;
  const path = (dx, dy) => { ctx.beginPath(); ctx.moveTo(-bw / 2 + skew + dx, -bh / 2 + dy); ctx.lineTo(bw / 2 + dx, -bh / 2 + dy); ctx.lineTo(bw / 2 - skew + dx, bh / 2 + dy); ctx.lineTo(-bw / 2 + dx, bh / 2 + dy); ctx.closePath(); };
  path(8 * u, 10 * u); ctx.fillStyle = "rgba(60,0,0,0.4)"; ctx.fill();
  path(0, 0); ctx.fillStyle = STYLE.color.deep; ctx.fill();
  ctx.lineWidth = 5 * u; ctx.strokeStyle = STYLE.color.gold; ctx.stroke();
}

// 黑色胶囊：承载说明文字，黄字黑底对比最强。
function capsule(ctx, text, size, u) {
  ctx.font = font(weightOf(STYLE.font.title), size, STYLE.font.title);
  const tw = ctx.measureText(text).width, ch = size * 1.9;
  ctx.fillStyle = STYLE.color.ink;
  ctx.beginPath(); ctx.roundRect(-tw / 2 - size, -ch / 2, tw + size * 2, ch, ch / 2); ctx.fill();
  ctx.fillStyle = STYLE.color.yellow; ctx.textAlign = "center"; ctx.fillText(text, 0, size * 0.36); ctx.textAlign = "left";
}

// 爆炸贴：多角星形贴纸，深红描边。
function burst(ctx, r, spikes, color, u) {
  ctx.beginPath();
  for (let i = 0; i < spikes * 2; i++) {
    const a = (i * Math.PI) / spikes, rr = i % 2 ? r * 0.8 : r;
    ctx.lineTo(Math.cos(a) * rr, Math.sin(a) * rr);
  }
  ctx.closePath();
  ctx.fillStyle = color; ctx.fill();
  ctx.lineWidth = 6 * u; ctx.lineJoin = "round"; ctx.strokeStyle = STYLE.color.deep; ctx.stroke();
}

function ribbon(ctx, text, x, y, u) {
  ctx.font = font(weightOf(STYLE.font.body), 22 * u, STYLE.font.body);
  const tw = ctx.measureText(text).width, bw = tw + 60 * u, bh = 44 * u;
  ctx.fillStyle = STYLE.color.gold;
  ctx.beginPath();
  ctx.moveTo(x - bw / 2 - 18 * u, y - bh / 2 + 8 * u); ctx.lineTo(x - bw / 2, y - bh / 2 + 8 * u);
  ctx.lineTo(x - bw / 2, y + bh / 2 + 8 * u); ctx.lineTo(x - bw / 2 - 18 * u, y + bh / 2 + 8 * u); ctx.lineTo(x - bw / 2 - 8 * u, y + 8 * u);
  ctx.closePath(); ctx.fill();
  ctx.beginPath();
  ctx.moveTo(x + bw / 2 + 18 * u, y - bh / 2 + 8 * u); ctx.lineTo(x + bw / 2, y - bh / 2 + 8 * u);
  ctx.lineTo(x + bw / 2, y + bh / 2 + 8 * u); ctx.lineTo(x + bw / 2 + 18 * u, y + bh / 2 + 8 * u); ctx.lineTo(x + bw / 2 + 8 * u, y + 8 * u);
  ctx.closePath(); ctx.fill();
  ctx.fillStyle = STYLE.color.yellow;
  ctx.fillRect(x - bw / 2, y - bh / 2, bw, bh);
  ctx.fillStyle = STYLE.color.bgOuter;
  ctx.textAlign = "center";
  ctx.fillText(text, x, y + 8 * u);
  ctx.textAlign = "left";
}

function sparkle(ctx, x, y, r, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x, y - r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.quadraticCurveTo(x, y, x, y + r);
  ctx.quadraticCurveTo(x, y, x - r, y);
  ctx.quadraticCurveTo(x, y, x, y - r);
  ctx.fill();
}

function sparkles(ctx, t, start, cx, cy, spread, u) {
  const pts = [[-1, -0.6, 1], [0.95, -0.7, 0.8], [-0.85, 0.7, 0.7], [1.05, 0.55, 1.1], [0.1, -1.05, 0.6]];
  pts.forEach(([px, py, s], i) => {
    const k = clamp((t - start - i * 0.05) / 0.5);
    if (k <= 0) return;
    // 闪一下：先放大再缩到常驻大小。
    const r = 30 * u * s * (0.55 + 0.45 * Math.sin(Math.PI * Math.min(1, k * 1.5)));
    sparkle(ctx, cx + px * spread, cy + py * spread * 0.45, r, STYLE.color.yellow);
  });
}

// 优惠券：两侧半圆缺口 + 竖向虚线分隔。投影用同一形状，缺口处透出底色。
function ticketPath(ctx, x, y, w, h, u) {
  const r = 14 * u;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x + w, y);
  ctx.lineTo(x + w, y + h / 2 - r);
  ctx.arc(x + w, y + h / 2, r, -Math.PI / 2, Math.PI / 2, true);
  ctx.lineTo(x + w, y + h);
  ctx.lineTo(x, y + h);
  ctx.lineTo(x, y + h / 2 + r);
  ctx.arc(x, y + h / 2, r, Math.PI / 2, -Math.PI / 2, true);
  ctx.closePath();
}

function ticket(ctx, x, y, w, h, split, u) {
  ticketPath(ctx, x + 8 * u, y + 10 * u, w, h, u);
  ctx.fillStyle = "rgba(60,0,0,0.35)";
  ctx.fill();
  ticketPath(ctx, x, y, w, h, u);
  ctx.fillStyle = STYLE.color.white;
  ctx.fill();
  ctx.save();
  ctx.clip();
  ctx.fillStyle = STYLE.color.bgInner;
  ctx.fillRect(x, y, split, h);
  ctx.restore();
  ctx.strokeStyle = STYLE.color.bgInner;
  ctx.lineWidth = 2 * u;
  ctx.setLineDash([6 * u, 6 * u]);
  ctx.beginPath(); ctx.moveTo(x + split + 14 * u, y + 12 * u); ctx.lineTo(x + split + 14 * u, y + h - 12 * u); ctx.stroke();
  ctx.setLineDash([]);
}

// 示意画面：一张商品页样子的界面（大图、属性、价格按钮），本地坐标原点在左上角；高亮目标是红色按钮。
function mockTarget(iw, ih) { return { x: iw * 0.68, y: ih * 0.55, w: iw * 0.26, h: ih * 0.12 }; }
function mockScreen(ctx, iw, ih, u) {
  ctx.fillStyle = "#FFFFFF"; ctx.fillRect(0, 0, iw, ih);
  ctx.fillStyle = "#FFF1E6"; ctx.fillRect(0, 0, iw, ih * 0.08);
  for (let i = 0; i < 3; i++) { ctx.fillStyle = "#F2C9B8"; ctx.beginPath(); ctx.arc((16 + i * 14) * u, ih * 0.04, 4 * u, 0, Math.PI * 2); ctx.fill(); }
  const px = iw * 0.035, py = ih * 0.13, pw = iw * 0.58, ph = ih * 0.8;
  const g = ctx.createLinearGradient(0, py, 0, py + ph);
  g.addColorStop(0, "#FFE9C7"); g.addColorStop(1, "#FFC88A");
  ctx.fillStyle = g; ctx.fillRect(px, py, pw, ph);
  // 商品：一只礼盒（示意）
  const bx = px + pw * 0.28, by = py + ph * 0.36, bw = pw * 0.44, bh = ph * 0.46;
  ctx.fillStyle = "rgba(122,0,8,0.18)"; ctx.beginPath(); ctx.ellipse(bx + bw / 2, by + bh + 6 * u, bw * 0.6, 10 * u, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = "#FF3B30"; ctx.fillRect(bx, by, bw, bh);
  ctx.fillStyle = "#D61F1F"; ctx.fillRect(bx - 6 * u, by - 18 * u, bw + 12 * u, 22 * u);
  ctx.fillStyle = "#FFB000"; ctx.fillRect(bx + bw / 2 - 9 * u, by - 18 * u, 18 * u, bh + 18 * u);
  ctx.beginPath(); ctx.ellipse(bx + bw / 2 - 18 * u, by - 26 * u, 18 * u, 10 * u, -0.5, 0, Math.PI * 2); ctx.ellipse(bx + bw / 2 + 18 * u, by - 26 * u, 18 * u, 10 * u, 0.5, 0, Math.PI * 2); ctx.fill();
  const sx = iw * 0.67, sw = iw * 0.29;
  [0.95, 0.7, 0.5].forEach((k, i) => { ctx.fillStyle = "#EFE3DC"; ctx.fillRect(sx, py + ih * (0.03 + i * 0.075), sw * k, ih * 0.03); });
  ctx.fillStyle = "#FF3B30"; ctx.fillRect(sx, py + ih * 0.27, sw * 0.42, ih * 0.06);
  const T = mockTarget(iw, ih);
  ctx.fillStyle = "#FF3B30"; ctx.beginPath(); ctx.roundRect(T.x, T.y, T.w, T.h, T.h / 2); ctx.fill();
  ctx.fillStyle = "#FFE45C"; ctx.fillRect(T.x + T.w * 0.24, T.y + T.h * 0.42, T.w * 0.52, T.h * 0.16);
  [0.9, 0.6].forEach((k, i) => { ctx.fillStyle = "#EFE3DC"; ctx.fillRect(sx, py + ih * (0.62 + i * 0.07), sw * k, ih * 0.026); });
}

// 场景内可见时返回位姿，否则返回 null（该时刻不画）。
const within = (t, [a, b]) => t >= a && t < b;
const fadeOut = (t, [, b], dur = 0.15) => 1 - cubicIn((t - (b - dur)) / dur);
// 只用来量字宽（分层时还没有画布）。
let measurer = null;
function measure(text, f) {
  measurer ??= new OffscreenCanvas(1, 1).getContext("2d");
  measurer.font = f;
  return measurer.measureText(text).width;
}

function layers(_params, w, h) {
  const u = h / 720, C = STYLE.color, out = [];
  // 底：渐变与缓慢旋转的放射光，按当前时刻整层画（转得很慢，不需要模糊）。
  out.push({ draw: (ctx, t) => rays(ctx, t, w, h) });

  // 标题：斜切深红横幅从左侧高速冲进来（标题框），白色立体大标题随后从 1.5 倍砸在横幅上，闪光环绕。不加副标题。
  const title = SCENES.title, titleSize = 96 * u, titleW = measure(COPY.title, font(700, titleSize, STYLE.font.title)), bw = titleW + 150 * u, bh = 150 * u;
  out.push({
    bounds: [-bw / 2 - 10 * u, -bh / 2 - 6 * u, bw / 2 + 18 * u, bh / 2 + 16 * u],
    pose: (t) => within(t, title) ? { x: w / 2 - (1 - quintOut(t / 0.3)) * w * 0.8, y: h * 0.52, rotation: TILT, opacity: fadeOut(t, title) } : null,
    draw: (ctx) => banner(ctx, bw, bh, u),
  });
  out.push({
    bounds: [-titleW / 2 - 20 * u, -titleSize, titleW / 2 + 30 * u, titleSize * 0.4],
    pose: (t) => within(t, title) && t >= 0.18 ? { x: w / 2, y: h * 0.52 + titleSize * 0.36, rotation: TILT, scale: impact(t, 0.18) * fadeOut(t, title) } : null,
    draw: (ctx) => extrude(ctx, COPY.title, 0, 0, titleSize, C.white, C.gold, u),
  });
  out.push({ draw: (ctx, t) => within(t, title) && sparkles(ctx, t, 0.45, w / 2, h * 0.5, 440 * u, u) });

  // 花字与关键词：黑底黄字胶囊“风格”先弹出；“不走样”超大黄色立体字带着白色爆炸贴一起从 1.5 倍砸下，闪光随后。
  const kw = SCENES.keyword, keySize = 150 * u, keyW = measure(COPY.keyword.key, font(700, keySize, STYLE.font.title)), ky = h * 0.6;
  out.push({
    bounds: [-keyW * 0.62, -keyW * 0.62, keyW * 0.62, keyW * 0.62],
    pose: (t) => within(t, kw) && t >= kw[0] + 0.12 ? { x: w / 2, y: ky - keySize * 0.32, rotation: TILT + t * 0.2, scale: impact(t, kw[0] + 0.12) * fadeOut(t, kw) } : null,
    draw: (ctx) => burst(ctx, keyW * 0.6, 14, C.white, u),
  });
  out.push({
    bounds: [-keyW / 2 - 20 * u, -keySize, keyW / 2 + 30 * u, keySize * 0.4],
    pose: (t) => within(t, kw) && t >= kw[0] + 0.12 ? { x: w / 2, y: ky, rotation: TILT, scale: impact(t, kw[0] + 0.12) * fadeOut(t, kw) } : null,
    draw: (ctx) => extrude(ctx, COPY.keyword.key, 0, 0, keySize, C.yellow, C.deep, u),
  });
  out.push({
    bounds: [-90 * u, -40 * u, 90 * u, 40 * u],
    pose: (t) => within(t, kw) && t >= kw[0] ? { x: w / 2 - keyW * 0.42, y: h * 0.24, rotation: TILT, scale: backOut((t - kw[0]) / 0.25) * fadeOut(t, kw) } : null,
    draw: (ctx) => capsule(ctx, COPY.keyword.lead, 34 * u, u),
  });
  out.push({ draw: (ctx, t) => within(t, kw) && sparkles(ctx, t, kw[0] + 0.4, w / 2, ky - keySize * 0.3, 380 * u, u) });

  // 图片与录屏容器 + 高亮：截图装在黄色粗边的海报框里（深红厚度 + 硬投影），整块从 1.5 倍砸下；左上角缎带写“示意画面”。
  // 高亮：目标从截图里放大弹出（冲击入场，黄色描边 + 深红厚度），闪光环绕，像把这个按钮拎到观众眼前。
  const media = SCENES.media, iw = w * 0.5, ih = iw * 0.62, fr = 14 * u, T = mockTarget(iw, ih), hlAt = media[0] + 1.1, mcx = w * 0.5, mcy = h * 0.54;
  const frame = (t) => within(t, media) && t >= media[0] ? { x: mcx, y: mcy, rotation: TILT, scale: impact(t, media[0], 0.32) * fadeOut(t, media) } : null;
  out.push({
    bounds: [-iw / 2 - fr - 4 * u, -ih / 2 - fr - 4 * u, iw / 2 + fr + 16 * u, ih / 2 + fr + 18 * u],
    pose: frame,
    draw: (ctx, t) => {
      ctx.fillStyle = C.deep; ctx.fillRect(-iw / 2 - fr + 10 * u, -ih / 2 - fr + 12 * u, iw + 2 * fr, ih + 2 * fr);
      ctx.fillStyle = C.yellow; ctx.fillRect(-iw / 2 - fr, -ih / 2 - fr, iw + 2 * fr, ih + 2 * fr);
      ctx.save(); ctx.translate(-iw / 2, -ih / 2); mockScreen(ctx, iw, ih, u);
      const k = clamp((t - hlAt) / 0.25);
      if (k > 0) { ctx.fillStyle = `rgba(26,10,10,${0.35 * k})`; ctx.fillRect(0, 0, iw, ih); }
      ctx.restore();
    },
  });
  out.push({
    bounds: [-120 * u, -30 * u, 120 * u, 40 * u],
    pose: (t) => { const f = frame(t); return f && t >= media[0] + 0.2 ? { x: mcx - iw / 2 + 70 * u, y: mcy - ih / 2 - fr - 2 * u, rotation: TILT, scale: backOut((t - media[0] - 0.2) / 0.3) * fadeOut(t, media) } : null; },
    draw: (ctx) => ribbon(ctx, COPY.media, 0, 0, u),
  });
  // 放大的目标：同一张示意画面裁出按钮区域放大 1.4 倍，位置跟随海报框的倾斜换算。
  const zoom = 1.4, tcx = T.x + T.w / 2 - iw / 2, tcy = T.y + T.h / 2 - ih / 2;
  const zx = mcx + tcx * Math.cos(TILT) - tcy * Math.sin(TILT), zy = mcy + tcx * Math.sin(TILT) + tcy * Math.cos(TILT);
  out.push({
    bounds: [-T.w * zoom / 2 - 14 * u, -T.h * zoom / 2 - 14 * u, T.w * zoom / 2 + 22 * u, T.h * zoom / 2 + 24 * u],
    pose: (t) => within(t, media) && t >= hlAt ? { x: zx, y: zy, rotation: TILT, scale: impact(t, hlAt, 0.3) * fadeOut(t, media) } : null,
    draw: (ctx) => {
      const zw = T.w * zoom + 16 * u, zh = T.h * zoom + 16 * u;
      ctx.fillStyle = C.deep; ctx.beginPath(); ctx.roundRect(-zw / 2 + 8 * u, -zh / 2 + 10 * u, zw, zh, zh / 2); ctx.fill();
      ctx.fillStyle = C.yellow; ctx.beginPath(); ctx.roundRect(-zw / 2, -zh / 2, zw, zh, zh / 2); ctx.fill();
      ctx.save(); ctx.beginPath(); ctx.roundRect(-T.w * zoom / 2, -T.h * zoom / 2, T.w * zoom, T.h * zoom, T.h * zoom / 2); ctx.clip();
      ctx.scale(zoom, zoom); ctx.translate(-(T.x + T.w / 2), -(T.y + T.h / 2)); mockScreen(ctx, iw, ih, u);
      ctx.restore();
    },
  });
  out.push({ draw: (ctx, t) => within(t, media) && sparkles(ctx, t, hlAt + 0.2, zx, zy, 150 * u, u) });

  // 数据：超大数字计数并砸下，说明胶囊随后弹出。
  const data = SCENES.data;
  out.push({
    bounds: [-330 * u, -300 * u, 150 * u, 30 * u],
    pose: (t) => within(t, data) ? { x: w * 0.47, y: h * 0.66, rotation: TILT, scale: impact(t, data[0], 0.3) * fadeOut(t, data) } : null,
    draw: (ctx, t) => {
      const n = Math.round(COPY.data.value * quintOut((t - data[0]) / 0.7));
      extrude(ctx, String(n), 0, 0, 300 * u, C.yellow, C.deep, u, STYLE.font.number, "right");
      extrude(ctx, COPY.data.unit, 8 * u, -100 * u, 140 * u, C.yellow, C.deep, u, STYLE.font.number, "left");
    },
  });
  out.push({
    bounds: [-180 * u, -34 * u, 180 * u, 34 * u],
    pose: (t) => within(t, data) && t >= data[0] + 0.55 ? { x: w * 0.5, y: h * 0.82, rotation: TILT, scale: backOut((t - data[0] - 0.55) / 0.3) * fadeOut(t, data) } : null,
    draw: (ctx) => capsule(ctx, COPY.data.label, 34 * u, u),
  });
  out.push({ draw: (ctx, t) => within(t, data) && sparkles(ctx, t, data[0] + 0.7, w * 0.5, h * 0.45, 380 * u, u) });

  // 人名条：优惠券从左侧滑入。
  const name = SCENES.name, tw = 420 * u, th = 110 * u;
  out.push({
    bounds: [0, 0, tw + 8 * u, th + 10 * u],
    pose: (t) => within(t, name)
      ? { x: w * 0.08 - (1 - quintOut((t - name[0] - 0.05) / 0.35)) * tw * 1.2, y: h * 0.7, opacity: fadeOut(t, name) }
      : null,
    draw: (ctx) => {
      ticket(ctx, 0, 0, tw, th, 170 * u, u);
      ctx.fillStyle = C.white;
      // 名字装在左侧票根里（170 宽）：名字长时整体缩小，左右各留约 25 的边（左边还有票根缺口）。
      ctx.font = font(weightOf(STYLE.font.title), 48 * u, STYLE.font.title);
      const nameSize = 48 * Math.min(1, (120 * u) / ctx.measureText(COPY.name.name).width);
      ctx.font = font(weightOf(STYLE.font.title), nameSize * u, STYLE.font.title);
      ctx.textAlign = "center";
      ctx.fillText(COPY.name.name, 85 * u, th / 2 + nameSize * 0.35 * u);
      ctx.textAlign = "left";
      ctx.fillStyle = C.ink;
      ctx.font = font(weightOf(STYLE.font.title), 32 * u, STYLE.font.title);
      ctx.fillText(COPY.name.role, 206 * u, th / 2 + 12 * u);
    },
  });

  // 收尾：黄色立体大字砸下，闪光环绕。
  const end = SCENES.end;
  out.push({
    bounds: [-400 * u, -80 * u, 410 * u, 30 * u],
    pose: (t) => t >= end[0] + 0.05 ? { x: w / 2, y: h * 0.56, rotation: TILT, scale: impact(t, end[0] + 0.05) } : null,
    draw: (ctx) => extrude(ctx, COPY.end, 0, 0, 84 * u, C.yellow, C.deep, u),
  });
  out.push({ draw: (ctx, t) => t >= end[0] && sparkles(ctx, t, end[0] + 0.3, w / 2, h * 0.5, 420 * u, u) });
  return out;
}

